#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> adj(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    auto bfs = [&](int start) {
        vector<int> dist(N + 1, -1);
        vector<int> q(N);
        int head = 0, tail = 0;

        dist[start] = 0;
        q[tail++] = start;
        int far = start;

        while (head < tail) {
            int u = q[head++];
            if (dist[u] > dist[far]) far = u;

            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q[tail++] = v;
                }
            }
        }

        return make_pair(far, dist[far]);
    };

    int A = bfs(1).first;
    int D = bfs(A).second;

    vector<int> parent(N + 1, 0);
    vector<int> order;
    order.reserve(N);

    parent[1] = 0;
    order.push_back(1);

    for (int i = 0; i < (int)order.size(); ++i) {
        int u = order[i];
        for (int v : adj[u]) {
            if (v == parent[u]) continue;
            parent[v] = u;
            order.push_back(v);
        }
    }

    vector<int> downH(N + 1, 0);
    vector<long long> downC(N + 1, 0);
    long long answer = 0;

    vector<pair<int, long long>> branches;

    for (int idx = N - 1; idx >= 0; --idx) {
        int u = order[idx];

        downH[u] = 0;
        downC[u] = 1;

        branches.clear();
        branches.push_back({0, 1});

        for (int v : adj[u]) {
            if (parent[v] == u) {
                int h = downH[v] + 1;
                long long c = downC[v];

                branches.push_back({h, c});

                if (h > downH[u]) {
                    downH[u] = h;
                    downC[u] = c;
                } else if (h == downH[u]) {
                    downC[u] += c;
                }
            }
        }

        sort(branches.begin(), branches.end());

        vector<pair<int, long long>> groups;
        groups.reserve(branches.size());

        for (auto p : branches) {
            if (groups.empty() || groups.back().first != p.first) {
                groups.push_back(p);
            } else {
                groups.back().second += p.second;
            }
        }

        int i = 0, j = (int)groups.size() - 1;

        while (i <= j) {
            int sum = groups[i].first + groups[j].first;

            if (sum < D) {
                ++i;
            } else if (sum > D) {
                --j;
            } else {
                if (i == j) {
                    if (groups[i].first * 2 == D) {
                        long long c = groups[i].second;
                        answer += c * (c - 1) / 2;
                    }
                    break;
                } else {
                    answer += groups[i].second * groups[j].second;
                    ++i;
                    --j;
                }
            }
        }
    }

    cout << D + 1 << '\n' << answer << '\n';

    return 0;
}
